from pathlib import Path
import json
import re

# ============================================================
# Purpose
# Enriches the converted Markdown files with the labels recovered during the Confluence extraction and reconciliation process.
#
# Inputs
# 
# Confluence-output\ – Markdown files generated by HTML_to_Markdown_bulk_converter.py
# reports\page_metadata.json – Page metadata generated by extract_labelled_pages.py
#
# Process
#
# Loads the page metadata file.
# Matches each Markdown file to its corresponding metadata entry.
# Replaces the default labels:
# - change-enablement
# - migrated-from-confluence
# with the actual label(s) extracted from Confluence.
# Preserves the migration labels:
# YAML
# - change-enablement
# - migrated-from-confluence
# 
# Removes the redundant "Change Enablement : " prefix from page titles.
# Updates the YAML front matter in each Markdown file.
# 
# Outputs
#
# Updated Markdown files containing:
# Correct page title
# Original Confluence labels
# Migration labels
# 
# Example
#
# Before:
# ---
# title: "Change Enablement : ADR009 - Adopt gRPC as our endpoint protocol for the insurance platform?"
# labels:
#  - change-enablement
#  - migrated-from-confluence
# ---
#
# After:
# ---
# title: "ADR009 - Adopt gRPC as our endpoint protocol for the insurance platform?"
# labels:
#  - architecture-decision-record
#  - change-enablement
#  - migrated-from-confluence
#---
# ============================================================


# ============================================================
# CONFIGURATION
# ============================================================

BASE_DIR = Path(__file__).parent

MARKDOWN_DIR = BASE_DIR / "Confluence-output"

METADATA_FILE = (
    BASE_DIR
    / "reports"
    / "page_metadata.json"
)

# ============================================================
# LOAD METADATA
# ============================================================

with open(
    METADATA_FILE,
    encoding="utf-8"
) as f:

    metadata = json.load(f)

print(
    f"Loaded {len(metadata)} metadata entries"
)

# ============================================================
# PROCESS MARKDOWN FILES
# ============================================================

updated = 0
not_found = 0

for md_file in MARKDOWN_DIR.rglob("*.md"):

    html_name = md_file.stem + ".html"

    if html_name not in metadata:

        not_found += 1
        continue

    page_info = metadata[html_name]

    page_title = page_info.get(
        "page_title",
        md_file.stem
    )

    labels = page_info.get(
        "labels",
        []
    )

    # --------------------------------------------------------
    # Read file
    # --------------------------------------------------------

    with open(
        md_file,
        encoding="utf-8"
    ) as f:

        content = f.read()

    # --------------------------------------------------------
    # Clean Title
    # --------------------------------------------------------

    page_title = re.sub(
        r"^Change Enablement\s*:\s*",
        "",
        page_title,
        flags=re.IGNORECASE
    )

    # --------------------------------------------------------
    # Build YAML
    # --------------------------------------------------------

    final_labels = []

    final_labels.extend(labels)

    if "change-enablement" not in final_labels:
        final_labels.append(
            "change-enablement"
        )

    if "migrated-from-confluence" not in final_labels:
        final_labels.append(
            "migrated-from-confluence"
        )

    yaml_lines = [
        "---",
        f'title: "{page_title}"',
        "labels:"
    ]

    for label in sorted(
        set(final_labels)
    ):

        yaml_lines.append(
            f"  - {label}"
        )

    yaml_lines.append("---")

    new_yaml = "\n".join(yaml_lines)

    # --------------------------------------------------------
    # Replace Existing YAML
    # --------------------------------------------------------

    content = re.sub(
        r"^---\n.*?\n---",
        new_yaml,
        content,
        flags=re.DOTALL
    )

    # --------------------------------------------------------
    # Save
    # --------------------------------------------------------

    with open(
        md_file,
        "w",
        encoding="utf-8"
    ) as f:

        f.write(content)

    updated += 1

# ============================================================
# SUMMARY
# ============================================================

print()
print("=" * 60)
print("LABEL INJECTION COMPLETE")
print("=" * 60)

print(f"Updated Markdown files : {updated}")
print(f"No metadata found      : {not_found}")